UPDATE flow_hist SET FLOW_AVR = #{flow}
WHERE AREA_CODE = #{area_code} AND DATA_TYPE = #{type} 
AND FLOW_DATE = #{where_date}

mapper.select:

		SELECT AVG(FLOW_AVR) AS DATA
		FROM flow_hist
		WHERE AREA_CODE = #{area_code} AND DATA_TYPE = #{type}
 		AND FLOW_DATE BETWEEN #{where_date} AND #{sdate}


SELECT IFNULL(FLOW_AVR, -99999) AS RAIN, FLOW_DATE AS RAIN_DATE
	FROM flow_hist
	WHERE DATA_TYPE = 'M' AND AREA_CODE = #{area_code}
	AND FLOW_DATE between #{sdate} and #{edate}
	ORDER BY FLOW_DATE
